function sortJsonByKeys(jsonObject) {
  // convert JSON object to array of key-value pairs
  const entries = Object.entries(jsonObject);

  // sort array based on key values (numeric keys are parsed as numbers)
  entries.sort(([keyA], [keyB]) => {
    const valueA = jsonObject[keyA];
    const valueB = jsonObject[keyB];

    // compare numeric keys directly
    if (Number.isInteger(Number(keyA)) && Number.isInteger(Number(keyB))) {
      return Number(keyA) - Number(keyB);
    }

    // convert non-numeric keys to strings for comparison
    const keyAString = String(keyA);
    const keyBString = String(keyB);

    let result = 0;

    // compare key strings lexicographically
    for (let I = 0; I < Math.min(keyAString.length, keyBString.length); i++) {
      result = keyAString.charCodeAt(i) - keyBString.charCodeAt(i);
      if (result !== 0) {
        return result;
      }
    }

    // compare key lengths
    result = keyAString.length - keyBString.length;
    return result !== 0 ? result : 0;
  });

  // convert sorted array back to JSON object
  const sortedObject = Object.fromEntries(entries);
  return sortedObject;
}
```

