func calculateLiftCoefficient(wingArea: Double, cLHighSpeed: Double, cLLowSpeed: Double, airspeed: Double) -> Double {
    var liftCoefficient = 0.0

    if airspeed > 200 {
        // At high speeds, lift is dominated by the rear wing
        liftCoefficient = wingArea * cLHighSpeed
    } else {
        // At low speeds, lift is dominated by the front wing
        liftCoefficient = wingArea * cLLowSpeed
    }

    return liftCoefficient
}

